-- Findie MVP: draft for an EMPTY PostgreSQL database with pgvector available.
-- Design companion: database-design.md. Not a production migration or auth policy.
-- UUIDs are generated by .NET, event times use timestamptz; no auth vendor schema.
BEGIN;
CREATE EXTENSION IF NOT EXISTS vector;
SET LOCAL TIME ZONE 'UTC';

CREATE TABLE app_users (
    id uuid PRIMARY KEY,
    auth_issuer text NOT NULL CHECK (btrim(auth_issuer) <> ''),
    auth_subject text NOT NULL CHECK (btrim(auth_subject) <> ''),
    display_name text NOT NULL CHECK (char_length(btrim(display_name)) BETWEEN 1 AND 120),
    disabled_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (auth_issuer, auth_subject)
);

CREATE TABLE reception_points (
    id uuid PRIMARY KEY,
    name text NOT NULL CHECK (btrim(name) <> ''),
    public_address text NOT NULL CHECK (btrim(public_address) <> ''),
    directions text,
    active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE point_staff (
    point_id uuid NOT NULL REFERENCES reception_points(id) ON DELETE RESTRICT,
    user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
    can_receive boolean NOT NULL DEFAULT false,
    can_return boolean NOT NULL DEFAULT false,
    assigned_at timestamptz NOT NULL DEFAULT now(),
    revoked_at timestamptz,
    PRIMARY KEY (point_id, user_id),
    CHECK (can_receive OR can_return)
);
CREATE INDEX point_staff_user_idx ON point_staff(user_id) WHERE revoked_at IS NULL;

CREATE TABLE items (
    id uuid PRIMARY KEY,
    posted_by uuid NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
    title text NOT NULL CHECK (char_length(btrim(title)) BETWEEN 1 AND 200),
    public_description text NOT NULL CHECK (char_length(btrim(public_description)) BETWEEN 1 AND 5000),
    found_area text NOT NULL CHECK (btrim(found_area) <> ''),
    found_time_precision text NOT NULL CHECK (found_time_precision IN ('unknown', 'date', 'range', 'exact')),
    found_on date,
    found_from timestamptz,
    found_until timestamptz,
    found_timezone text NOT NULL DEFAULT 'Asia/Ho_Chi_Minh',
    custody_kind text NOT NULL CHECK (custody_kind IN ('person', 'point', 'external')),
    holder_user_id uuid REFERENCES app_users(id) ON DELETE RESTRICT,
    holder_point_id uuid REFERENCES reception_points(id) ON DELETE RESTRICT,
    external_name text,
    external_public_address text,
    external_instructions text,
    lifecycle text NOT NULL DEFAULT 'active' CHECK (lifecycle IN ('active', 'returned', 'deleted')),
    publication_state text NOT NULL DEFAULT 'draft' CHECK (publication_state IN ('draft', 'published', 'hidden')),
    content_version bigint NOT NULL DEFAULT 1 CHECK (content_version > 0),
    custody_version bigint NOT NULL DEFAULT 1 CHECK (custody_version > 0),
    row_version bigint NOT NULL DEFAULT 1 CHECK (row_version > 0),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (
        (found_time_precision = 'unknown' AND found_on IS NULL AND found_from IS NULL AND found_until IS NULL) OR
        (found_time_precision = 'date' AND found_on IS NOT NULL AND found_from IS NULL AND found_until IS NULL) OR
        (found_time_precision = 'exact' AND found_on IS NULL AND found_from IS NOT NULL AND found_until IS NULL) OR
        (found_time_precision = 'range' AND found_on IS NULL AND found_from IS NOT NULL AND found_until IS NOT NULL AND found_from <= found_until)
    ),
    CHECK (
        (custody_kind = 'person' AND holder_user_id IS NOT NULL AND holder_point_id IS NULL AND external_name IS NULL AND external_public_address IS NULL AND external_instructions IS NULL) OR
        (custody_kind = 'point' AND holder_user_id IS NULL AND holder_point_id IS NOT NULL AND external_name IS NULL AND external_public_address IS NULL AND external_instructions IS NULL) OR
        (custody_kind = 'external' AND holder_user_id IS NULL AND holder_point_id IS NULL AND external_name IS NOT NULL AND btrim(external_name) <> '' AND external_public_address IS NOT NULL AND btrim(external_public_address) <> '')
    )
);
CREATE INDEX items_public_feed_idx ON items(created_at DESC, id) WHERE publication_state = 'published' AND lifecycle = 'active';
CREATE INDEX items_author_idx ON items(posted_by, created_at DESC);
CREATE INDEX items_holder_user_idx ON items(holder_user_id) WHERE holder_user_id IS NOT NULL;
CREATE INDEX items_holder_point_idx ON items(holder_point_id) WHERE holder_point_id IS NOT NULL;
CREATE INDEX items_found_date_idx ON items(found_on) WHERE found_on IS NOT NULL;
CREATE INDEX items_found_range_idx ON items(found_from, found_until) WHERE found_from IS NOT NULL;

-- Reserve keys before upload; retain unlinked/replaced objects until R2 deletion succeeds.
CREATE TABLE stored_objects (
    id uuid PRIMARY KEY,
    owner_user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
    bucket text NOT NULL CHECK (btrim(bucket) <> ''),
    object_key text NOT NULL CHECK (btrim(object_key) <> ''),
    object_kind text NOT NULL CHECK (object_kind IN ('original', 'sanitized')),
    object_state text NOT NULL DEFAULT 'reserved' CHECK (object_state IN ('reserved', 'validated', 'delete_pending', 'deleted')),
    sha256 text CHECK (sha256 ~ '^[0-9a-f]{64}$'),
    content_type text CHECK (content_type IN ('image/jpeg', 'image/png', 'image/webp')),
    byte_size bigint CHECK (byte_size > 0),
    width integer CHECK (width > 0),
    height integer CHECK (height > 0),
    expires_at timestamptz,
    cleanup_next_at timestamptz,
    cleanup_attempts integer NOT NULL DEFAULT 0 CHECK (cleanup_attempts >= 0),
    last_error_code text,
    created_at timestamptz NOT NULL DEFAULT now(),
    validated_at timestamptz,
    deleted_at timestamptz,
    UNIQUE (bucket, object_key),
    CHECK (object_state <> 'validated' OR (sha256 IS NOT NULL AND content_type IS NOT NULL AND byte_size IS NOT NULL AND width IS NOT NULL AND height IS NOT NULL AND validated_at IS NOT NULL)),
    CHECK ((object_state = 'deleted') = (deleted_at IS NOT NULL)),
    CHECK (object_state <> 'reserved' OR expires_at IS NOT NULL)
);
CREATE INDEX stored_objects_cleanup_idx ON stored_objects(cleanup_next_at, expires_at) WHERE object_state <> 'deleted';

CREATE TABLE item_images (
    id uuid PRIMARY KEY,
    item_id uuid NOT NULL REFERENCES items(id) ON DELETE RESTRICT,
    position smallint NOT NULL CHECK (position > 0),
    original_object_id uuid NOT NULL UNIQUE REFERENCES stored_objects(id) ON DELETE RESTRICT,
    sanitized_object_id uuid UNIQUE REFERENCES stored_objects(id) ON DELETE RESTRICT,
    content_version bigint NOT NULL DEFAULT 1 CHECK (content_version > 0),
    processing_state text NOT NULL DEFAULT 'pending' CHECK (processing_state IN ('pending', 'processing', 'needs_review', 'ready', 'failed', 'rejected')),
    review_state text NOT NULL DEFAULT 'pending' CHECK (review_state IN ('pending', 'approved', 'rejected')),
    sensitive_regions jsonb CHECK (jsonb_typeof(sensitive_regions) = 'array'),
    redaction_model_id text,
    redaction_model_revision text,
    redaction_profile text,
    reviewed_by uuid REFERENCES app_users(id) ON DELETE RESTRICT,
    reviewed_at timestamptz,
    failure_code text,
    retired_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (id, item_id),
    CHECK (original_object_id IS DISTINCT FROM sanitized_object_id),
    CHECK ((review_state = 'pending' AND reviewed_by IS NULL AND reviewed_at IS NULL) OR (review_state IN ('approved', 'rejected') AND reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL)),
    CHECK (processing_state NOT IN ('needs_review', 'ready') OR (sanitized_object_id IS NOT NULL AND redaction_model_id IS NOT NULL AND redaction_model_revision IS NOT NULL AND redaction_profile IS NOT NULL)),
    CHECK (processing_state <> 'ready' OR review_state = 'approved'),
    CHECK (processing_state <> 'rejected' OR review_state = 'rejected')
);
CREATE UNIQUE INDEX item_images_position_idx ON item_images(item_id, position) WHERE retired_at IS NULL;

CREATE TABLE verification_questions (
    item_id uuid NOT NULL REFERENCES items(id) ON DELETE RESTRICT,
    slot smallint NOT NULL CHECK (slot BETWEEN 1 AND 3),
    question_text text NOT NULL CHECK (char_length(btrim(question_text)) BETWEEN 1 AND 500),
    PRIMARY KEY (item_id, slot)
);

CREATE TABLE claims (
    id uuid PRIMARY KEY,
    item_id uuid NOT NULL REFERENCES items(id) ON DELETE RESTRICT,
    claimant_user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
    reviewer_user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
    source_custody_version bigint NOT NULL CHECK (source_custody_version > 0),
    status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected')),
    decided_by uuid REFERENCES app_users(id) ON DELETE RESTRICT,
    decided_at timestamptz,
    decision_note text CHECK (char_length(decision_note) <= 2000),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (id, item_id),
    UNIQUE (id, status),
    CHECK (claimant_user_id <> reviewer_user_id),
    CHECK ((status = 'pending' AND decided_by IS NULL AND decided_at IS NULL) OR (status <> 'pending' AND decided_by IS NOT NULL AND decided_by = reviewer_user_id AND decided_at IS NOT NULL))
);
CREATE INDEX claims_item_idx ON claims(item_id, status, created_at);
CREATE INDEX claims_claimant_idx ON claims(claimant_user_id, created_at DESC);
CREATE INDEX claims_reviewer_idx ON claims(reviewer_user_id, status, created_at);

-- Copy every question at submission; NULL answers keep the required-answer policy open.
CREATE TABLE claim_answers (
    claim_id uuid NOT NULL REFERENCES claims(id) ON DELETE RESTRICT,
    slot smallint NOT NULL CHECK (slot BETWEEN 1 AND 3),
    question_text_snapshot text NOT NULL CHECK (char_length(btrim(question_text_snapshot)) BETWEEN 1 AND 500),
    answer_text text CHECK (char_length(btrim(answer_text)) BETWEEN 1 AND 2000),
    PRIMARY KEY (claim_id, slot)
);

CREATE TABLE conversations (
    claim_id uuid PRIMARY KEY,
    approval_status text NOT NULL DEFAULT 'approved' CHECK (approval_status = 'approved'),
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (claim_id, approval_status) REFERENCES claims(id, status) ON DELETE RESTRICT ON UPDATE RESTRICT
);

CREATE TABLE messages (
    id uuid PRIMARY KEY,
    conversation_id uuid NOT NULL REFERENCES conversations(claim_id) ON DELETE RESTRICT,
    sender_user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
    client_message_id uuid NOT NULL,
    message_sequence bigint GENERATED ALWAYS AS IDENTITY UNIQUE,
    body text NOT NULL CHECK (char_length(btrim(body)) BETWEEN 1 AND 4000),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (conversation_id, sender_user_id, client_message_id)
);
CREATE INDEX messages_history_idx ON messages(conversation_id, message_sequence);

CREATE TABLE intake_requests (
    id uuid PRIMARY KEY,
    item_id uuid NOT NULL REFERENCES items(id) ON DELETE RESTRICT,
    requested_by uuid NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
    target_point_id uuid NOT NULL REFERENCES reception_points(id) ON DELETE RESTRICT,
    source_custody_version bigint NOT NULL CHECK (source_custody_version > 0),
    status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'received', 'rejected')),
    decided_by uuid REFERENCES app_users(id) ON DELETE RESTRICT,
    decided_at timestamptz,
    decision_note text CHECK (char_length(decision_note) <= 2000),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (id, item_id),
    CHECK ((status = 'pending' AND decided_by IS NULL AND decided_at IS NULL) OR (status <> 'pending' AND decided_by IS NOT NULL AND decided_at IS NOT NULL))
);
CREATE INDEX intake_point_queue_idx ON intake_requests(target_point_id, status, created_at);
CREATE INDEX intake_item_idx ON intake_requests(item_id, status);
CREATE INDEX intake_requester_idx ON intake_requests(requested_by, created_at DESC);

-- Immutable snapshots contain public custody data/IDs, never a personal home address.
CREATE TABLE custody_events (
    id uuid PRIMARY KEY,
    item_id uuid NOT NULL REFERENCES items(id) ON DELETE RESTRICT,
    event_kind text NOT NULL CHECK (event_kind IN ('registered', 'received', 'returned')),
    custody_version bigint NOT NULL CHECK (custody_version > 0),
    actor_user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
    intake_request_id uuid UNIQUE,
    claim_id uuid,
    recipient_user_id uuid REFERENCES app_users(id) ON DELETE RESTRICT,
    from_custody jsonb CHECK (jsonb_typeof(from_custody) = 'object'),
    to_custody jsonb CHECK (jsonb_typeof(to_custody) = 'object'),
    verification_note text CHECK (char_length(verification_note) <= 2000),
    occurred_at timestamptz NOT NULL,
    recorded_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (item_id, custody_version),
    FOREIGN KEY (intake_request_id, item_id) REFERENCES intake_requests(id, item_id) ON DELETE RESTRICT,
    FOREIGN KEY (claim_id, item_id) REFERENCES claims(id, item_id) ON DELETE RESTRICT,
    CHECK (
        (event_kind = 'registered' AND from_custody IS NULL AND to_custody IS NOT NULL AND intake_request_id IS NULL AND claim_id IS NULL AND recipient_user_id IS NULL) OR
        (event_kind = 'received' AND from_custody IS NOT NULL AND to_custody IS NOT NULL AND intake_request_id IS NOT NULL AND claim_id IS NULL AND recipient_user_id IS NULL) OR
        (event_kind = 'returned' AND from_custody IS NOT NULL AND to_custody IS NULL AND intake_request_id IS NULL)
    )
);
CREATE UNIQUE INDEX custody_one_return_idx ON custody_events(item_id) WHERE event_kind = 'returned';
CREATE UNIQUE INDEX custody_one_registration_idx ON custody_events(item_id) WHERE event_kind = 'registered';
CREATE INDEX custody_event_time_idx ON custody_events(item_id, occurred_at, id);
CREATE INDEX custody_claim_idx ON custody_events(claim_id) WHERE claim_id IS NOT NULL;

CREATE TABLE ai_jobs (
    id uuid PRIMARY KEY,
    item_id uuid NOT NULL REFERENCES items(id) ON DELETE RESTRICT,
    image_id uuid,
    job_kind text NOT NULL CHECK (job_kind IN ('redact_image', 'embed_text', 'embed_image')),
    source_version bigint NOT NULL CHECK (source_version > 0),
    source_sha256 text NOT NULL CHECK (source_sha256 ~ '^[0-9a-f]{64}$'),
    model_id text NOT NULL CHECK (btrim(model_id) <> ''),
    model_revision text NOT NULL CHECK (btrim(model_revision) <> ''),
    processing_profile text NOT NULL CHECK (btrim(processing_profile) <> ''),
    status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'running', 'retry', 'succeeded', 'failed', 'obsolete')),
    attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    max_attempts integer NOT NULL CHECK (max_attempts > 0),
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    lease_token uuid,
    lease_until timestamptz,
    last_error_code text,
    created_at timestamptz NOT NULL DEFAULT now(),
    finished_at timestamptz,
    FOREIGN KEY (image_id, item_id) REFERENCES item_images(id, item_id) ON DELETE RESTRICT,
    CHECK ((job_kind = 'embed_text' AND image_id IS NULL) OR (job_kind IN ('redact_image', 'embed_image') AND image_id IS NOT NULL)),
    CHECK ((status = 'running' AND lease_token IS NOT NULL AND lease_until IS NOT NULL) OR (status <> 'running' AND lease_token IS NULL AND lease_until IS NULL)),
    CHECK ((status IN ('succeeded', 'failed', 'obsolete')) = (finished_at IS NOT NULL))
);
CREATE UNIQUE INDEX ai_jobs_text_target_idx ON ai_jobs(item_id, source_version, job_kind, model_id, model_revision, processing_profile) WHERE image_id IS NULL;
CREATE UNIQUE INDEX ai_jobs_image_target_idx ON ai_jobs(image_id, source_version, job_kind, model_id, model_revision, processing_profile) WHERE image_id IS NOT NULL;
CREATE INDEX ai_jobs_ready_idx ON ai_jobs(next_attempt_at, id) WHERE status IN ('pending', 'retry');
CREATE INDEX ai_jobs_expired_lease_idx ON ai_jobs(lease_until) WHERE status = 'running';

CREATE TABLE item_embeddings (
    id uuid PRIMARY KEY,
    item_id uuid NOT NULL REFERENCES items(id) ON DELETE RESTRICT,
    image_id uuid,
    modality text NOT NULL CHECK (modality IN ('text', 'image')),
    source_version bigint NOT NULL CHECK (source_version > 0),
    source_sha256 text NOT NULL CHECK (source_sha256 ~ '^[0-9a-f]{64}$'),
    model_id text NOT NULL CHECK (btrim(model_id) <> ''),
    model_revision text NOT NULL CHECK (btrim(model_revision) <> ''),
    processing_profile text NOT NULL CHECK (btrim(processing_profile) <> ''),
    dimensions integer NOT NULL DEFAULT 2048 CHECK (dimensions = 2048),
    embedding vector(2048) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (image_id, item_id) REFERENCES item_images(id, item_id) ON DELETE RESTRICT,
    CHECK ((modality = 'text' AND image_id IS NULL) OR (modality = 'image' AND image_id IS NOT NULL))
);
CREATE UNIQUE INDEX embeddings_text_identity_idx ON item_embeddings(item_id, model_id, model_revision, processing_profile) WHERE modality = 'text';
CREATE UNIQUE INDEX embeddings_image_identity_idx ON item_embeddings(image_id, model_id, model_revision, processing_profile) WHERE modality = 'image';
CREATE INDEX embeddings_search_scope_idx ON item_embeddings(modality, model_id, model_revision, processing_profile);
CREATE INDEX embeddings_item_idx ON item_embeddings(item_id);
-- Exact cosine search first; vector(2048) exceeds the 2000-dimension vector ANN index limit.

CREATE TABLE idempotency_keys (
    actor_user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
    idempotency_key uuid NOT NULL,
    operation text NOT NULL CHECK (btrim(operation) <> ''),
    request_sha256 text NOT NULL CHECK (request_sha256 ~ '^[0-9a-f]{64}$'),
    resource_type text NOT NULL CHECK (resource_type IN ('item', 'image', 'claim', 'intake', 'custody_event')),
    resource_id uuid NOT NULL,
    response_status smallint NOT NULL CHECK (response_status BETWEEN 200 AND 299),
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (actor_user_id, idempotency_key)
);
-- resource_id is intentionally polymorphic; authorization is rechecked on every replay.
COMMIT;
